const i=JSON.parse('{"workId":"liezi","chapter":{"id":"liezi_ch-8","workId":"liezi","order":8,"title":"說符","difficulty":2,"estimatedMinutes":46,"passageIds":["liezi_ch-8_p-1","liezi_ch-8_p-2","liezi_ch-8_p-3","liezi_ch-8_p-4","liezi_ch-8_p-5","liezi_ch-8_p-6","liezi_ch-8_p-7","liezi_ch-8_p-8","liezi_ch-8_p-9","liezi_ch-8_p-10","liezi_ch-8_p-11","liezi_ch-8_p-12","liezi_ch-8_p-13","liezi_ch-8_p-14","liezi_ch-8_p-15","liezi_ch-8_p-16","liezi_ch-8_p-17","liezi_ch-8_p-18","liezi_ch-8_p-19","liezi_ch-8_p-20","liezi_ch-8_p-21","liezi_ch-8_p-22","liezi_ch-8_p-23","liezi_ch-8_p-24","liezi_ch-8_p-25"],"tags":[]},"passages":[{"id":"liezi_ch-8_p-1","workId":"liezi","chapterId":"liezi_ch-8","index":1,"canonicalText":"子列子學於壺丘子林。壺丘子林曰：「子知持後，則可言持身矣。」列子曰：「願聞持後。」曰：「顧若影，則知之。」列子顧而觀影：形枉則影曲，形直則影正。然則枉直者，定在於形，不在於影。形動作於先，影隨應於後。持後之道，因形以應變也。","readingAid":{"translation":"列子跟隨老師壺丘子林學習大道。壺丘子林指點他說：你如果真正懂得了如何甘居於眾人之後（持後），才可以同你談論如何立身處世的根本大法了。列子恭敬地說：弟子渴望聽聞持後的深層真諦。老師說：回頭看看你自己的影子，你就徹底明白了。列子回頭仔細觀察自己的影子：身軀形體彎曲則地上的影子自然彎曲，身軀形體筆直挺拔則地上的影子自然端正。既然如此，那麼影子的彎曲與端正，其決定權完全在於身軀形體本身，而根本不在於影子自身。身軀形體的動作在先發起，而地上的影子在後自然隨順響應。所以甘居於後（持後）的最高處世大道，正是順應客觀事物的既成形態去靈活應變自如啊！","analysis":"【題解與背景】\\\\n本段選自《列子》〈說符〉第 109 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「子列子學於壺丘子林壺丘子林曰子知持後則可……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「子」、「列」、「子」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《列子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：liezi_ch-8_p-1）。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-1_s-1","liezi_ch-8_p-1_s-2","liezi_ch-8_p-1_s-3","liezi_ch-8_p-1_s-4","liezi_ch-8_p-1_s-5","liezi_ch-8_p-1_s-6","liezi_ch-8_p-1_s-7","liezi_ch-8_p-1_s-8"]},{"id":"liezi_ch-8_p-2","workId":"liezi","chapterId":"liezi_ch-8","index":2,"canonicalText":"關尹謂子列子曰：「言美者應美，言惡者應惡；身大者影大，身小者影小。名自命也，事自應也。故善言者，美應自至；善行者，福祿自來。慎其所發，則知其所歸矣。」","readingAid":{"translation":"關尹對列子說：說出美好言語的人，得到的也必然是美好的回應；說出惡毒言語的人，得到的也必然是惡毒的回報；這就像身體高大的人，他的影子就大，身體矮小的人，他的影子就小一樣。一個人的名聲是由他自己的所作所為決定的，事情的結果也是由事情的起因自然相應而來的。所以，善於說好話的人，美好的回應自然會到來；善於做好事的人，福氣與爵祿自然會降臨。只要謹慎對待自己發出的每一句話、每一個行動，就能夠預知它們最終會帶來什麼樣的歸宿和結果了。","analysis":"【訓詁與名物】：「關尹」春秋時函谷關令尹喜。「子列子」列禦寇。「應」回應、報應。「名自命也」名聲是自己給自己決定的。「事自應也」事情的結果是自然相應而來的。「福祿」福氣與爵祿（官職俸祿）。「慎其所發」謹慎對待自己的言行出發點。「歸」歸宿、結果。\\\\n\\\\n【章法與結構】：本段是一篇邏輯嚴密的因果論說文。先用「言語（美惡）」與「形影（大小）」兩個直觀的類比，提出「同類相應」的普遍規律；接著點出核心論點（名自命，事自應）；然後推導出行善言善行的必然好結果；最後以「慎發知歸」的警句作結，落實到個人的道德實踐上。\\\\n\\\\n【思想與義理】：這段話雖然出自道家典籍《列子》，但其蘊含的思想卻具有強烈的儒家和墨家色彩，體現了中國古代普遍的「因果感應」與「形影相隨」的報應觀。它強調外部世界（他人、社會、命運）對個體的反饋，完全取決於個體自身的言行。這是一種非常積極、主動的人生觀，它將命運的決定權交還給了個人（名自命也）。「慎其所發」更是與儒家「慎獨」、「出言有尺」的修養功夫如出一轍，教導人們要在因果的源頭上把握自己的行為，從而掌控自己的人生走向。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-2_s-1","liezi_ch-8_p-2_s-2","liezi_ch-8_p-2_s-3","liezi_ch-8_p-2_s-4","liezi_ch-8_p-2_s-5","liezi_ch-8_p-2_s-6","liezi_ch-8_p-2_s-7"]},{"id":"liezi_ch-8_p-3","workId":"liezi","chapterId":"liezi_ch-8","index":3,"canonicalText":"子列子曰：「天下之物，莫不由符而驗。發於此而應於彼，動於微而顯於著。善為符者，見其萌而知其終，睹其始而識其成。此說符之大要也。」","readingAid":{"translation":"列子說：全天下世間的一切事物，沒有哪一個不是通過內外符節相合的客觀因果徵兆來得到檢驗驗證的（由符而驗）。在近處此地發起一個微小因緣，必然會在遙遠彼方引發深遠響應；在事物極其隱微萌芽之際輕輕一動，必然會在未來的宏大結果中顯著呈現。真正善於洞察符節因果規律的智者，看見事物剛萌發的幼芽就能預知其最終的走向結局，目睹事情剛開始的開端就能洞識其未來的成敗得失。這正是〈說符〉全篇最為宏大的核心綱要所在啊！","analysis":"【篇旨與說符題旨符驗因果見萌知終系統預測學】全面揭示〈說符〉篇名之深意——「符」即因果徵兆之相合驗證，確立「見其萌知其終、睹其始識其成」的微觀洞察與系統預測學總綱。\\\\n【詞義訓詁】「由符而驗」：符，古代信物符節，比喻因果相應、徵兆驗證；「發此應彼動微顯著」：非線性因果與蝴蝶效應；「說符之大要」：全卷總綱。\\\\n【前瞻性思維】掌握事物演化的底層因果規律，在萌芽階段見微知著，是高階決策者的核心洞察力。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-3_s-1","liezi_ch-8_p-3_s-2","liezi_ch-8_p-3_s-3","liezi_ch-8_p-3_s-4","liezi_ch-8_p-3_s-5"]},{"id":"liezi_ch-8_p-4","workId":"liezi","chapterId":"liezi_ch-8","index":4,"canonicalText":"晉文公出亡，過曹，曹共公不禮焉，欲觀其駢脅，駢脅而浴。僖負羈之妻曰：「吾觀晉公子，從者三人，皆霸王之佐也。公子若反國，必霸諸侯，而誅無禮。曹其首也。子何不先自結焉？」僖負羈乃饋盤飧，寘璧焉。文公受飧而反璧。及文公即位，興兵伐曹，入其國，令三軍毋入僖負羈之宮。故知先機者存，慢禮者亡。","readingAid":{"translation":"晉文公重耳早年流亡流亡在列國途中，路過曹國，曹共公對他極其傲慢無禮，甚至想偷看重耳傳說中肋骨連成一片的異相（駢脅），趁著重耳洗澡時無禮窺視。曹國賢大夫僖負羈的妻子敏銳地對丈夫說：我觀察晉國公子重耳，跟隨他的三位心腹重臣（狐偃、趙衰、賈佗），全都是具有輔佐帝王成就霸業之才的天下奇才！晉公子一旦將來返回晉國奪取君位，必定會稱霸諸侯，起兵討伐那些當年對他無禮侮辱的國家，而我們曹國必定是第一個首當其衝被懲罰的目標！您為什麼不現在就趁早私下結交善待他呢？僖負羈聽從了妻子的卓見，於是備辦了一盤豐盛的飯食送給重耳，並在盤底暗中放置了一塊珍貴的玉璧。重耳感激地喫下了飯食，但將玉璧禮貌地退還給了他。後來晉文公果然即位登基稱霸，大舉興兵討伐曹國，攻破曹國都城之後，文公嚴厲下令三軍將士：嚴禁任何人騷擾侵犯僖負羈的府邸！所以深刻洞悉未來先機的人能夠長保平安，傲慢無禮侮辱賢才的人必將招致滅頂之災！","analysis":"【篇旨與僖負羈妻先知先覺晉文公伐曹保全府邸】記錄晉文公流亡過曹之歷史名篇——曹共公窺駢脅傲慢致亡國，僖負羈妻見微知著饋盤飧保全宗族，展現超前戰略預見與識人智慧。\\\\n【詞義訓詁】「駢脅」：駢，音便；肋骨連成一體之異相；「寘璧」：寘通置，放置玉璧以表敬重；「毋入僖負羈之宮」：知恩圖報與軍事保護令。\\\\n【戰略預見力】在弱小低谷時精準識拔潛力股並建立善緣，是化解未來地緣浩劫的最高生存智慧。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-4_s-1","liezi_ch-8_p-4_s-2","liezi_ch-8_p-4_s-3","liezi_ch-8_p-4_s-4","liezi_ch-8_p-4_s-5","liezi_ch-8_p-4_s-6","liezi_ch-8_p-4_s-7","liezi_ch-8_p-4_s-8","liezi_ch-8_p-4_s-9"]},{"id":"liezi_ch-8_p-5","workId":"liezi","chapterId":"liezi_ch-8","index":5,"canonicalText":"楚莊王伐陳，勝之，欲以為縣。申叔時使於齊反，謁王。王曰：「陳可為縣乎？」對曰：「不可。昔者有牽牛以蹊人之田而奪之牛者，牽牛蹊田，信有罪矣；而奪之牛，罰亦重矣。今陳侯有罪，君伐而縣之，何以示天下之公乎？」莊王乃封陳而還。天下皆服其義。","readingAid":{"translation":"楚莊王興兵討伐陳國，大獲全勝攻滅了陳國，打算直接吞併陳國將其改設為楚國的一個縣。大夫申叔時出使齊國完成使命歸來，進宮拜見楚莊王。莊王得意地問道：把陳國改設為楚國的一個縣，你看怎麼樣？申叔時回答說：萬萬不可！從前有一個人牽著牛踩踏了別人的農田莊稼，農田主人便憤怒地強行搶奪沒收了那人的整頭牛；牽牛踩踏農田，確實是有過錯犯罪了；但直接強搶別人的整頭牛作為賠償，這懲罰也實在太過沉重過分了！如今陳國國君雖然荒淫有罪，大王出兵討伐他伸張正義，隨後卻直接吞併其國土改設為自己的私縣，您又拿什麼來向全天下昭示您出兵的大公無私呢？楚莊王聽後豁然開朗，於是重新冊立陳國後人恢復其封國，隨後班師回朝。全天下諸侯百姓無不由衷心悅誠服楚國的天下大義！","analysis":"【篇旨與申叔時蹊田奪牛之喻楚莊王復陳立信】申叔時以「蹊田奪牛罰太重」為精妙比喻，勸阻楚莊王吞併陳國改縣，力主「滅其罪而存其祀」，展現正義之師不可假公濟私的國際法理。\\\\n【詞義訓詁】「蹊人之田」：蹊，音西，踐踏踩碎農田；「奪之牛罰亦重」：過罰不相當、假借正義行掠奪之實；「縣之」：將諸侯國降為直屬郡縣。\\\\n【國際政治倫理】維和討伐必須恪守程序正義與道義底線，切莫因貪圖私利將正義之戰異化為侵略吞併，方能贏得國際社會長久信任。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-5_s-1","liezi_ch-8_p-5_s-2","liezi_ch-8_p-5_s-3","liezi_ch-8_p-5_s-4","liezi_ch-8_p-5_s-5","liezi_ch-8_p-5_s-6","liezi_ch-8_p-5_s-7","liezi_ch-8_p-5_s-8","liezi_ch-8_p-5_s-9"]},{"id":"liezi_ch-8_p-6","workId":"liezi","chapterId":"liezi_ch-8","index":6,"canonicalText":"子列子居鄭圃，食不足，面有飢色。客有言之鄭子產曰：「列禦寇，蓋有道之士也，居君之國而窮，君無乃為不好士乎？」子產乃使官往遺之粟。子列子出見使者，再拜而辭。使者去，妻望之而拊心曰：「妾聞為悌子者，妻子蒙福。今先生面有飢色，客遺之粟，先生不受，命也夫！」子列子笑曰：「子產非自知我也。以人之言而遺我粟，至其罪我也，亦必以人之言。吾是以不受也。」其後，民果作難，子產治之，受其賜者皆獲罪，唯列子免焉。","readingAid":{"translation":"列子隱居在鄭國圃田，家中糧食匱乏短缺，臉上帶有長期的飢餓菜色。有一位訪客在鄭國宰相子產面前進言說：列禦寇是一位真正身懷至高大道的高士，居住在您執政的國家之中卻窮困挨餓，君王難道不怕全天下人說您不尊重愛護人才嗎？子產聽後立刻派遣官吏運送糧食穀粟前去救濟資助列子。列子親自走出來接見使者，再三躬身拜謝但堅決推辭拒絕接受糧食。使者離去之後，列子的妻子看著空空如也的糧袋悲痛地捶胸痛哭道：我聽說作為得道賢士的妻子兒女，理應蒙受福祿；如今先生臉上滿是飢餓之色，貴人主動送來救命糧食，先生卻堅決不肯接受，這難道就是我們的苦命嗎！列子笑著對妻子解釋說：子產並非真正發自內心深刻理解識拔我的品德啊！他今天是因為聽信了別人的閒話才送給我糧食，將來有一天他要治我的罪、懲罰我的時候，也必定會因為聽信別人的謠言讒言啊！我正是因為這個深層原因才堅決不肯接受他的賞賜啊！後來沒過多久，鄭國政壇果然爆發了政治動亂，子產下令嚴酷清查清洗，當年接受過子產私恩賞賜的士人全都受到牽連獲罪下獄，唯獨列子安然無恙免除了這場政治浩劫！","analysis":"【篇旨與列子辭子產之粟預見政治風暴獨立自守】記載列子「面有飢色」卻堅辭子產所贈之粟，洞悉「以人言遺粟、亦必以人言加罪」的深層政治風險，最終在政變中安然免禍。\\\\n【詞義訓詁】「拊心」：拊，音撫，捶胸痛哭；「非自知我也」：非出自對其大道的深層認同，乃受制於世俗名聲所累；「受賜者皆獲罪」：無功受祿必被捲入派系政治清算。\\\\n【獨立人格與政治遠見】不被短期的物質施捨所誘惑，保持個體人格的絕對獨立，是遠離政治風暴與派系傾軋的至高智慧。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-6_s-1","liezi_ch-8_p-6_s-2","liezi_ch-8_p-6_s-3","liezi_ch-8_p-6_s-4","liezi_ch-8_p-6_s-5","liezi_ch-8_p-6_s-6","liezi_ch-8_p-6_s-7","liezi_ch-8_p-6_s-8","liezi_ch-8_p-6_s-9","liezi_ch-8_p-6_s-10"]},{"id":"liezi_ch-8_p-7","workId":"liezi","chapterId":"liezi_ch-8","index":7,"canonicalText":"楊朱曰：「利出者實及，怨往者害來。發於此而應於外者唯情，是故賢者慎所出。」","readingAid":{"translation":"楊朱說：給予別人利益的人，實際的好處也會回報到他身上；向別人發送怨恨的人，災害也必然會降臨到他頭上。從自己內心發出，並且在外部世界產生相應回報的，只有人的真實情感與心意。正因為如此，賢明的人總是對自己發出的言行和情感極為謹慎。","analysis":"【訓詁與名物】：「利出者」發出利益給別人的人。「實及」實質性的好處惠及自身。「怨往者」將怨恨發往別人的人。「害來」災害降臨。「情」這裡指人的真實情感、心意或態度。「慎所出」謹慎對待自己發出的一切（言、行、情）。\\\\n\\\\n【章法與結構】：本段結構與前一段關尹的論述極為相似。前兩句是工整的對偶，從正（利）反（怨）兩方面闡述因果報應的規律；第三句點出這種感應的核心樞紐是「情」；最後一句得出結論，強調「慎所出」。\\\\n\\\\n【思想與義理】：這段話進一步深化了前文關於「因果感應」的探討。楊朱在這裡指出，人與人之間、人與世界之間的互動，本質上是一種「情（情感、意念）」的能量交換。你給出善意和利益（利出），世界就回饋你實惠（實及）；你給出惡意和怨恨（怨往），世界就回饋你災禍（害來）。這種「作用力與反作用力」的社會法則，要求我們不僅要約束表面的言行，更要淨化內心的「情」。賢者之所以為賢，就在於他們深刻洞察了這條法則，從而在源頭上（慎所出）把控自己的命運。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-7_s-1","liezi_ch-8_p-7_s-2","liezi_ch-8_p-7_s-3"]},{"id":"liezi_ch-8_p-8","workId":"liezi","chapterId":"liezi_ch-8","index":8,"canonicalText":"楊子之鄰人亡羊，既率其黨，又請楊子之豎追之。楊子曰：「嘻！亡一羊何追者之眾？」鄰人曰：「多岐路。」既反，問：「獲羊乎？」曰：「亡之矣。」曰：「奚亡之？」曰：「岐路之中又有岐焉，吾不知所之，所以反也。」楊子戚然變容，不言者移時，不笑者竟日。門人怪之，請曰：「羊，賤畜，又非夫子之有，而損言笑者何哉？」楊子不答，門人不獲所命。弟子孟孫陽出，以告心都子。心都子他日與孟孫陽偕入，而問曰：「昔有昆弟三人，遊齊、魯之間，同師而學，進仁義之道而歸。其父曰：『仁義之道若何？』伯曰：『仁義使我愛身而後名。』仲曰：『仁義使我殺身以成名。』叔曰：『仁義使我身名並全。』彼三術相反，而同出於儒。孰是孰非邪？」楊子曰：「人有濱河而居者，習於水，勇於泅，操舟鬻渡，利供百口，裹糧就學者成徒，而溺死者幾半。本學泅不學溺，而利害如此。若以為孰是孰非？」心都子嘿然而出。孟孫陽讓之曰：「何吾子問之迂，夫子答之僻？吾惑愈甚。」心都子曰：「大道以多岐亡羊，學者以多方喪生。學非本不同，非本不一，而末異若是。唯歸同反一，為亡得喪。子長先生之門，習先生之道，而不達先生之況也，哀哉！」","readingAid":{"translation":"楊朱的一位鄰居丟失了一隻羊，鄰居不僅率領了整個家族的親友，又特地前來請求借用楊朱的小書童一同幫忙去追尋羊。楊朱驚訝地說：哎呀！僅僅丟失了一隻羊罷了，為什麼需要出動這麼多的人去追趕呢？鄰居回答說：因為岔路太多了（多岐路）！過了大半天，眾人空手返回了，楊朱問：羊找到了嗎？鄰居嘆氣說：徹底丟失了。楊朱問：為什麼會丟失呢？鄰居回答說：因為岔路之中又分叉出無數條岔路，我們完全不知道羊究竟跑向了哪條岔路，所以只好放棄折返回來了。楊朱聽後神色嚴肅淒然變色，長久沉默一言不發，整整一整天沒有露出一絲笑容（不笑者竟日）。門下弟子們對此感到無比奇怪，上前請教說：羊不過是微不足道的卑賤牲畜罷了，更何況那又不是老師您自己家的羊，您為什麼為此一整天不言不笑呢？楊朱沉默不予回答，弟子們始終無法理解老師的深意。弟子孟孫陽走出來，把這件怪事告訴了心都子。改天心都子同孟孫陽一同走進來拜見楊朱，心都子請教發問道：從前有親兄弟三個人，一同遊歷在齊國與魯國之間，拜在同一位老師門下求學，學成仁義之道後一同返回家鄉。他們的父親問道：你們所學的仁義之道究竟是怎樣的呢？大哥回答說：仁義之道教導我愛惜保全自己的生命，將個人名譽置於生命之後；二哥回答說：仁義之道教導我甘願捨生取義殺身成仁，以此來成就崇高功名；三弟回答說：仁義之道教導我既要保全自身生命又要成全名譽，做到身名兩全。這三種人生道路完全截然相反，然而全部出自同一位儒家老師的門下。請問老師：這三種學說究竟誰是誰非呢？楊朱回答說：從前有一個住在江河邊上的人，精通水性，極其勇敢善於游泳，每天划船擺渡販賣渡河服務，賺取的利潤足以供養全家上百口人的生活；許多人自備乾糧前來投奔拜他為師學習游泳，跟隨他求學的徒弟絡繹不絕，然而在學游泳的徒弟中溺水淹死的人竟然幾乎佔了一半！他們本意是前來學習游泳本領的，絕不是前來學習被水淹死的，然而最終產生的利益與禍害卻竟然如此截然相反！依你看來，這究竟誰是誰非呢？心都子聽後若有所悟，默默無言地退了出來。孟孫陽責怪抱怨心都子說：為什麼你剛才問得如此迂迴轉折，而老師回答得又如此偏僻古怪呢？我心中的困惑反而越來越深重了！心都子感嘆道：大道因為岔路太多而導致迷失了羊（大道以多岐亡羊），求學問道的人因為方法宗派繁雜太多而導致喪失了寶貴的生命本性（學者以多方喪生）！真理大道最初原本沒有什麼不同，本體原本沒有什麼二致，然而流傳演變到了末梢末端卻產生了如此巨大的分歧與偏差！唯有回歸大道的純一同體、反求自性本真（歸同反一），才不會有任何得失迷茫的痛苦。你在先生門下學習侍奉了這麼多年，每天學習先生的至道，卻完全無法理解先生以多岐亡羊所作的深沉比喻，這真是太令人悲哀了啊！","analysis":"【篇旨與岐路亡羊多方喪生學術異化與歸同反一哲學認識論巔峯】中國哲學史最著名、最具思想震撼力之寓言——楊朱借「多岐亡羊」痛惜「學者以多方喪生」，心都子以「兄弟三人同學儒而三術相反」、楊朱以「學泅溺死幾半」為喻，深刻批判學術分化異化與意識形態爭端導致人類喪失生命本真。\\\\n【詞義訓詁】「大道以多岐亡羊」：真理之路一旦被繁瑣宗派末流所割裂，必致迷失方向；「學者以多方喪生」：求學偏執於繁文縟節反而扼殺天性；「歸同反一」：超越門戶之見、回歸大道本體。\\\\n【知識論批判】深刻揭示信息過載、宗派紛爭與過度細分對真理本質的遮蔽，呼喚回歸根本、守住初心。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-8_s-1","liezi_ch-8_p-8_s-2","liezi_ch-8_p-8_s-3","liezi_ch-8_p-8_s-4","liezi_ch-8_p-8_s-5","liezi_ch-8_p-8_s-6","liezi_ch-8_p-8_s-7","liezi_ch-8_p-8_s-8","liezi_ch-8_p-8_s-9","liezi_ch-8_p-8_s-10","liezi_ch-8_p-8_s-11","liezi_ch-8_p-8_s-12","liezi_ch-8_p-8_s-13","liezi_ch-8_p-8_s-14","liezi_ch-8_p-8_s-15","liezi_ch-8_p-8_s-16","liezi_ch-8_p-8_s-17","liezi_ch-8_p-8_s-18","liezi_ch-8_p-8_s-19","liezi_ch-8_p-8_s-20","liezi_ch-8_p-8_s-21","liezi_ch-8_p-8_s-22","liezi_ch-8_p-8_s-23","liezi_ch-8_p-8_s-24","liezi_ch-8_p-8_s-25","liezi_ch-8_p-8_s-26","liezi_ch-8_p-8_s-27","liezi_ch-8_p-8_s-28","liezi_ch-8_p-8_s-29","liezi_ch-8_p-8_s-30"]},{"id":"liezi_ch-8_p-9","workId":"liezi","chapterId":"liezi_ch-8","index":9,"canonicalText":"楊朱之弟曰布，衣素衣而出。天雨，解素衣，衣緇衣而反。其狗不知，迎而吠之。楊布怒，將撲之。楊朱曰：「子無撲矣，子亦猶是也。嚮者使汝狗白而往，黑而來，豈能無怪哉？」","readingAid":{"translation":"楊朱的親弟弟名叫楊布，早晨出門時身上穿著一件雪白的白衣服（素衣）。半路上天空下起了大雨，楊布脫下了被淋濕的白衣服，換穿了一件黑色的黑衣服（緇衣）回家。他家裡養的那條狗認不出他來，迎上前衝著他狂吠咆哮不止。楊布勃然大怒，操起木棍就準備狠狠痛打那條狗。楊朱急忙攔阻他說：你千萬不要去打它啊！換作是你自己，你也同樣會犯這種錯誤的啊！剛才如果換作是你家的狗，出門時全身雪白，回來時卻突然全身漆黑，難道你心中能不感到奇怪驚訝而懷疑它嗎？","analysis":"【篇旨與楊布打狗換位思考與表象認知批判】極具生活智慧之微型寓言——楊布衣白而出衣黑而返遭家犬吠叫，楊朱以「狗白往黑來子亦怪之」勸阻痛打，確立「反求諸己、換位思考、不被表象蒙蔽」的處事哲學。\\\\n【詞義訓詁】「素衣／緇衣」：白衣與黑衣；「子亦猶是」：設身處地換位思考；「豈能無怪」：理解他人因外在表象變化產生誤解的客觀合理性。\\\\n【溝通心理學】在人際衝突與誤解面前，切莫一味歸咎他人，首先反省自身外部形象與行為變化，以包容心化解矛盾。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-9_s-1","liezi_ch-8_p-9_s-2","liezi_ch-8_p-9_s-3","liezi_ch-8_p-9_s-4","liezi_ch-8_p-9_s-5","liezi_ch-8_p-9_s-6","liezi_ch-8_p-9_s-7"]},{"id":"liezi_ch-8_p-10","workId":"liezi","chapterId":"liezi_ch-8","index":10,"canonicalText":"楊朱曰：「行善不以為名而名從之；名不與利期而利歸之；利不與爭期而爭及之。故君子必慎為善。」","readingAid":{"translation":"楊朱說：踐行善行美德從不把博取虛名作為企圖，然而美好的聲譽自然會隨之而來；名望聲譽從不主動去追求利益財富，然而實質的利益自然會歸附於名望；巨額利益從不主動去引發爭鬥仇恨，然而殘酷的爭奪殺戮自然會尾隨利益降臨而至！所以有德君子在行善修德的每一個環節，都必須極致謹慎防範啊！","analysis":"【題解與背景】\\\\n本段選自《列子》〈說符〉第 118 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「楊朱曰行善不以為名而名從之名不與利期而利……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「楊」、「朱」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《列子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：liezi_ch-8_p-10）。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-10_s-1","liezi_ch-8_p-10_s-2","liezi_ch-8_p-10_s-3","liezi_ch-8_p-10_s-4","liezi_ch-8_p-10_s-5"]},{"id":"liezi_ch-8_p-11","workId":"liezi","chapterId":"liezi_ch-8","index":11,"canonicalText":"昔人言有知不死之道者，燕君使人受之，不捷，而言者死。燕君甚怒其使者，將加誅焉。倖臣諫曰：「人所憂者莫急乎死，己所重者莫過乎生。彼自喪其生，安能令君不死也？」乃不誅。有齊子亦欲學其道，聞言者之死，乃撫膺而恨。富子聞而笑之曰：「夫所欲學不死，其人已死，而猶恨之，是不知所以為學。」鬍子曰：「富子之言非也。凡人有術不能行者有矣，能行而無其術者亦有矣。衛人有善數者，臨死，以決喻其子。志其言而不能行也。他人問之，以其父所言告之。問者用其言而行其術，與其父無差焉。若然，死者奚為不能言生術哉？」","readingAid":{"translation":"從前有人宣稱自己掌握了令人長生不死的神妙道術，燕國國君派遣特使前往向他求學學習；使者尚未趕到，那位宣稱不死的人自己就先病死了。燕君勃然大怒責怪使者行動遲緩，下令將使者依律斬首處死。身邊的寵臣進諫說：世人內心最為焦慮恐懼的事莫過於死亡，自身最為珍貴看重的事莫過於生命。那個自稱長生的人連他自己的生命都無法保全而病死了，他又怎麼可能真正掌握讓君王長生不死的法術呢？燕君聽後這才取消了死刑。齊國有一位士人原本也極其渴望向那人學習長生術，聽聞那人病死的消息後，竟然捶胸頓足長籲短嘆遺憾不已（撫膺而恨）。富子聽聞後嘲笑齊國士人說：你想去學習長生不死之術，那個傳授者自己都已經病死了，你竟然還在那裡為沒學到而感到遺憾，這簡直是完全不懂得求學的底層邏輯啊！這時鬍子反駁說：富子的說法是偏頗片面的！世間凡是掌握理論技術卻自身無法身體力行實踐的人是客觀存在的，自身能夠動手實踐卻不懂得理論技術的人同樣是客觀存在的。衛國有一個精通高深數學算術的大師，臨死前把核心計算祕訣傳授給了自己的兒子；兒子雖然把父親的言論祕訣牢牢記在心中卻根本無法熟練運用操作；後來別人前來向他請教，兒子把父親當年傳授的祕訣原話一字不差地告訴了來訪者；請教者運用這些祕訣理論去推演實踐，其高超水平竟然同那位老數學家完全毫無差別！既然如此，那個病死的人又憑什麼不能掌握長生保健的理論知識呢？","analysis":"【篇旨與不死之術求仙諷刺與知行分立認識論】圍繞「自稱不死者病死」引發的三重論辯（燕君寵臣破除迷信、富子嘲笑齊子、鬍子論知行分立），深刻辨析「理論知識（知）」與「實踐能力（行）」的複雜分離現象。\\\\n【詞義訓詁】「彼自喪其生安能令君不死」：戳穿長生騙局的邏輯鐵證；「撫膺而恨」：執迷不悟盲目信奉長生神話；「有術不能行，能行無其術」：理論與實踐脫節之科學哲學命題。\\\\n【科學理性與批判思維】既辛辣諷刺了統治階級對長生不老術的荒謬迷信，又客觀探討了理論傳播與個體實踐能力之間的差異。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-11_s-1","liezi_ch-8_p-11_s-2","liezi_ch-8_p-11_s-3","liezi_ch-8_p-11_s-4","liezi_ch-8_p-11_s-5","liezi_ch-8_p-11_s-6","liezi_ch-8_p-11_s-7","liezi_ch-8_p-11_s-8","liezi_ch-8_p-11_s-9","liezi_ch-8_p-11_s-10","liezi_ch-8_p-11_s-11","liezi_ch-8_p-11_s-12","liezi_ch-8_p-11_s-13","liezi_ch-8_p-11_s-14","liezi_ch-8_p-11_s-15"]},{"id":"liezi_ch-8_p-12","workId":"liezi","chapterId":"liezi_ch-8","index":12,"canonicalText":"邯鄲之民，以正月之旦獻鳩於簡子，簡子大悅，厚賞之。客問其故。簡子曰：「正旦放生，示有恩也。」客曰：「民知君之慾放之，故競而捕之，死者眾矣。君如欲生之，不若禁民勿捕。捕而放之，恩過不相補矣。」簡子曰：「然。」","readingAid":{"translation":"趙國邯鄲的百姓，在正月初一元旦這一天紛紛捕捉野鳩鳥進獻給執政趙簡子，趙簡子大喜過望，給予進獻者豐厚的金錢賞賜。身邊的門客好奇詢問其中的緣由。趙簡子高興地說：在正月初一這一天舉行放生儀式，是為了向天下昭示我的仁慈恩德啊！門客直言進諫說：百姓們正是因為知道您喜歡在大年初一舉行放生，所以纔在節前爭先恐後進山瘋狂捕捉鳩鳥，在捕捉與運輸過程中折騰死掉的鳥兒不計其數啊！您如果真的發自內心想讓鳥兒好好活著（生之），不如直接下令嚴禁百姓捕鳥。像現在這樣先讓百姓殘酷捕捉而後您再來假惺惺放生，您所施展的那點虛偽微薄恩德，根本無法彌補大量生靈慘死的大罪過啊！趙簡子聽後如夢初醒說：您說得太對了！","analysis":"【篇旨與邯鄲放生善惡相抵偽善批判公共政策反噬效應】中國生態倫理與公共政策史上最著名的「偽善放生」批判寓言——趙簡子為示恩元旦放生，引發百姓瘋狂捕鳥致生靈塗炭，門客痛斥「捕而放之恩過不相補」，揭示政策動機與實際後果的嚴重背離。\\\\n【詞義訓詁】「示有恩」：為政治表演與虛名而行善；「競而捕之死者眾」：政策激勵引發的嚴重次生危害；「恩過不相補」：偽善收益遠低於造成的實質破壞。\\\\n【現代公共政策反思】精闢揭示「眼鏡蛇效應（Cobra Effect）」與形式主義行善之害，確立評判任何政策的標準是客觀實際後果而非道德口號。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-12_s-1","liezi_ch-8_p-12_s-2","liezi_ch-8_p-12_s-3","liezi_ch-8_p-12_s-4","liezi_ch-8_p-12_s-5","liezi_ch-8_p-12_s-6","liezi_ch-8_p-12_s-7","liezi_ch-8_p-12_s-8"]},{"id":"liezi_ch-8_p-13","workId":"liezi","chapterId":"liezi_ch-8","index":13,"canonicalText":"齊田氏祖於庭，食客千人。中坐有獻魚鴈者。田氏視之，乃歎曰：「天之於民厚矣！殖五穀，生魚鳥，以為之用。」眾客和之如響。鮑氏之子年十二，預於次，進曰：「不如君言。天地萬物，與我並生類也。類無貴賤，徒以小大智力而相制，迭相食；非相為而生之。人取可食者而食之，豈天本為人生之？且蚊蚋噆膚，虎狼食肉，非天本為蚊蚋生人、虎狼生肉者哉？」","readingAid":{"translation":"齊國貴族田氏在自家宏偉的中庭大宴賓客舉行祭祖大典，前來赴宴的門客食客多達上千人之眾。宴席進行到一半時，有人進獻呈上鮮美的活魚與大雁。田氏看著這些山珍海味，不禁感慨萬千長嘆道：上天對我們人類的恩德實在太過深厚了！在大地上繁育五穀雜糧，在江河天空中化育魚蝦飛鳥，專門用來供養我們人類享用啊！滿堂的上千名食客紛紛阿諛奉承附和贊同，響應之聲如同雷鳴回聲。這時，在末席列席的一位鮑氏家族的十二歲小男孩（鮑氏之子），主動跨前一步走到大殿中央反駁道：事情根本不像您所說的那樣！天地宇宙間的萬事萬物，與我們人類一樣都是並存於大自然中的同等生命物種（與我並生類也）！生命物種之間原本就沒有高低貴賤之分，只不過是憑藉體型大小與智力力量的強弱在互相制約、弱肉強食互為食物鏈罷了（迭相食），上天絕對不是為了某一個物種才刻意去生發化育另一個物種的！我們人類捕獲那些能夠食用的動植物來喫，難道能荒謬地說上天原本就是專門為了供養人類才生發它們的嗎？按照您這種荒唐邏輯，蚊蟲吸食人類的皮膚血液（蚊蚋噆膚），猛虎野狼捕食人類的血肉，難道也能說上天當初原本就是專門為了供養蚊蟲才生發了人類、專門為了供養虎狼才生發了人類的血肉嗎？","analysis":"【篇旨與鮑氏之子十二歲反人類中心主義生態哲學巔峯】中國古代思想史上最具震撼力、最激進的反人類中心主義宣言——十二歲鮑氏之子直面田氏與千名食客，以「萬物與我並生、類無貴賤、迭相食非相為生、蚊蚋噆膚虎狼食人」駁倒「天生萬物養人」的神創論偏見！\\\\n【詞義訓詁】「與我並生類也」：物種平等的現代生態倫理觀；「迭相食」：客觀生物食物鏈與自然選擇規律；「蚊蚋噆膚」：噆，音咱，叮咬叮吸；以反向例證徹底擊碎人類中心主義傲慢。\\\\n【生態哲學與無神論】兩千年前便確立了純粹客觀唯物主義自然觀與生物平等觀，超越了西方傳統神學人類中心主義，閃耀著耀眼的理性光芒。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-13_s-1","liezi_ch-8_p-13_s-2","liezi_ch-8_p-13_s-3","liezi_ch-8_p-13_s-4","liezi_ch-8_p-13_s-5","liezi_ch-8_p-13_s-6","liezi_ch-8_p-13_s-7","liezi_ch-8_p-13_s-8","liezi_ch-8_p-13_s-9","liezi_ch-8_p-13_s-10","liezi_ch-8_p-13_s-11","liezi_ch-8_p-13_s-12"]},{"id":"liezi_ch-8_p-14","workId":"liezi","chapterId":"liezi_ch-8","index":14,"canonicalText":"齊有貧者，常乞於城市。城市患其亟也，眾莫之與。遂適田氏之廄，從馬醫作役，而假食郭中。人戲之曰：「從馬醫而食，不以辱乎？」乞兒曰：「天下之辱莫過於乞。乞猶不辱，豈辱馬醫哉？」","readingAid":{"translation":"齊國有一個極度貧困的人，常年在城市街頭乞討為生。城裡的市民百姓厭煩他天天頻繁乞討討要，大家再也沒有誰願意施捨給他任何財物了。於是他來到齊國貴族田氏的馬廄之中，跟隨給馬治病的馬醫充當打雜苦役，以此在城郭外圍換取粗茶淡飯自食其力。有人看見後故意戲弄嘲笑他說：你如今竟然淪落到跟隨一個低賤的馬醫當僕役混飯喫，難道不覺得這太過屈辱恥辱了嗎？這位昔日的乞丐坦然回答說：天底下最深重的恥辱莫過於伸手向人乞討。我當年連沿街乞討尚且都不覺得恥辱，如今靠自己的雙手辛勤勞動侍奉馬醫自食其力，又有什麼好感到恥辱的呢！","analysis":"【篇旨與乞兒從馬醫勞動自立與榮辱觀】通過乞丐轉為馬醫苦役自食其力的故事，深刻解構世俗虛偽的職業歧視與榮辱觀，確立「乞討為天下大辱、自食其力絕非恥辱」的勞動尊嚴論。\\\\n【詞義訓詁】「患其亟」：亟，音氣，頻繁；厭煩其頻繁乞討；「假食」：依靠勞動換取食物；「豈辱馬醫」：勞動光榮、自食其力無可指摘。\\\\n【勞動價值與人格尊嚴】打破職業貴賤的世俗偏見，強調自食其力是維護個體人格尊嚴的真正底線。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-14_s-1","liezi_ch-8_p-14_s-2","liezi_ch-8_p-14_s-3","liezi_ch-8_p-14_s-4","liezi_ch-8_p-14_s-5","liezi_ch-8_p-14_s-6","liezi_ch-8_p-14_s-7"]},{"id":"liezi_ch-8_p-15","workId":"liezi","chapterId":"liezi_ch-8","index":15,"canonicalText":"宋人有遊於道，得人遺契者，歸而藏之，密數其齒。告鄰人曰：「吾富可待矣。」鄰人曰：「契者，彼之券也，非汝之積也。無實而求得，惑之甚矣。」","readingAid":{"translation":"宋國有一個在道路上漫步遊歷的人，在路上偶然撿到了別人遺失丟棄的借據契約（遺契），他如獲至寶帶回家中隱藏珍藏起來，私下裡偷偷密密麻麻數著契約木券上的刻齒金額（密數其齒）。他興奮地對鄰居炫耀說：我馬上就要大富大貴發大財啦！鄰居冷靜地指點他說：契約木券，那是別人之間發生經濟往來的債權憑證罷了，根本不是你自己辛勤勞動積累的財富資產啊！自己毫無真實的勞動付出與實質資產，卻妄想憑藉一張撿來的廢紙契約發大財，這簡直是愚昧困惑到了極點啊！","analysis":"【題解與背景】\\\\n本段選自《列子》〈說符〉第 123 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「宋人有遊於道得人遺契者歸而藏之密數其齒告……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「宋」、「人」、「有」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《列子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：liezi_ch-8_p-15）。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-15_s-1","liezi_ch-8_p-15_s-2","liezi_ch-8_p-15_s-3","liezi_ch-8_p-15_s-4","liezi_ch-8_p-15_s-5"]},{"id":"liezi_ch-8_p-16","workId":"liezi","chapterId":"liezi_ch-8","index":16,"canonicalText":"人有枯梧樹者，其鄰父言枯梧之樹不祥。其人遽而伐之。鄰人父因請以為薪。其人乃不悅曰：「鄰人之父徒欲為薪，而教吾伐之也。與我鄰若此，其險豈可哉？」","readingAid":{"translation":"有一個人家中院子裡生長著一棵枯死的梧桐樹，他的鄰居老者對他說：枯死的梧桐樹立在院子裡是不吉利的凶兆不祥。這人一聽心中恐慌，急忙把枯梧桐樹砍伐倒了下來。這時鄰居老者走上前順便請求將砍倒的枯木送給自己當柴火燒。那人一聽頓時無比惱怒不高興地說：這個鄰居老頭只不過是自己想白白得到柴火罷了，才故意編造謊言教唆我把它砍掉的啊！同這樣居心險惡的人做鄰居，他的險惡用心簡直太可怕了！","analysis":"【篇旨與伐枯梧為薪動機揣測與人際猜忌心理學】先秦心理學極其精妙的「動機歸因偏差」寓言——鄰父好心提醒不祥並順請為薪，主人立刻全盤否定其善意，將其妖魔化為「徒欲為薪之險惡」，揭示人際猜疑鏈的自我強化機制。\\\\n【詞義訓詁】「枯梧不祥」：古代迷信風水忌諱；「徒欲為薪」：主觀惡意揣測動機；「其險豈可」：將合理利益訴求無限上綱為陰謀詭計。\\\\n【心理認知偏差】揭示人類在人際關係中極易陷入「陰謀論歸因」，過度解讀他人動機往往會破壞正常的人際信任。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-16_s-1","liezi_ch-8_p-16_s-2","liezi_ch-8_p-16_s-3","liezi_ch-8_p-16_s-4","liezi_ch-8_p-16_s-5","liezi_ch-8_p-16_s-6"]},{"id":"liezi_ch-8_p-17","workId":"liezi","chapterId":"liezi_ch-8","index":17,"canonicalText":"人有亡鈇者，意其鄰之子。視其行步，竊鈇也；顏色，竊鈇也；言語，竊鈇也；作動態度，無為而不竊鈇也。俄而抇其谷而得其鈇，他日復見其鄰人之子，動作態度，無似竊鈇者。","readingAid":{"translation":"有一個丟失了砍柴鐵斧的人（亡鈇者），內心主觀懷疑是鄰居家的兒子偷走了自己的斧頭。自此之後他暗中觀察鄰居的兒子：看他走路的步伐神態，怎麼看都像是一個偷斧頭的賊；看他臉上的神色表情，怎麼看都像是一個偷斧頭的賊；聽他說話的語氣口吻，怎麼聽都像是一個偷斧頭的賊；他的一舉一動一態一勢，沒有哪一樣不像是一個偷斧頭的賊！過了一段時間，那人在自己家的山谷泥坑中翻找挖掘（抇其谷），忽然找到了自己當初遺忘丟失的鐵斧！過幾天他再次看見鄰居家兒子的時候，發現那孩子的一舉一動、神態舉止，再也沒有哪一點像是偷過斧頭的人了！","analysis":"【篇旨與疑鄰盜斧確認偏誤（Confirmation Bias）心理學千古經典】世界認知心理學史上最著名的「確認偏誤」公案——主觀認定鄰子偷斧則其步、色、言、動無一不像賊；一旦找回斧頭則其神態無一像賊，深刻揭示先入為主的成見如何徹底扭曲人類的客觀感知。\\\\n【詞義訓詁】「鈇」：鈇通斧，斧頭；「抇」：音戶，挖掘翻找；「作動態度無為不竊鈇」：主觀偏見對感官信息的主動扭曲與自我驗證。\\\\n【現代認知科學】早於現代心理學兩千年精確描摹「確認偏誤」機制，告誡人們在司法裁判、管理決策與人際交往中必須徹底排除先入為主的成見。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-17_s-1","liezi_ch-8_p-17_s-2","liezi_ch-8_p-17_s-3","liezi_ch-8_p-17_s-4","liezi_ch-8_p-17_s-5","liezi_ch-8_p-17_s-6"]},{"id":"liezi_ch-8_p-18","workId":"liezi","chapterId":"liezi_ch-8","index":18,"canonicalText":"狐丘丈人謂孫叔敖曰：「人有三怨，子知之乎？」孫叔敖曰：「何謂也？」對曰：「爵高者人妬之，官大者主惡之，祿厚者怨歸之。」孫叔敖曰：「吾爵益高，吾志益下；吾官益大，吾心益小；吾祿益厚，吾施益博。以是免於三怨，可乎？」狐丘丈人曰：「善哉！言乎。」","readingAid":{"translation":"隱士狐丘丈人對楚國名相孫叔敖說：在官場仕途之中存在著三種必然招致怨恨的兇險規律（人有三怨），您知道嗎？孫叔敖恭敬地問道：這是什麼意思呢？狐丘丈人回答說：官爵地位崇高顯赫的人，同僚眾人必定會嫉妒他（爵高者人妬之）；官位權力龐大重大的人，最高君主往往會猜忌厭惡他（官大者主惡之）；俸祿財富優厚龐大的人，社會民怨必定會歸咎歸結於他（祿厚者怨歸之）！孫叔敖平靜回答說：我每當官爵地位變得更加崇高時，我的心志態度反而更加謙遜居下；我每當官職權力變得更加龐大時，我的行事處事反而更加謹小慎微戒慎恐懼；我每當俸祿待遇變得更加豐厚時，我拿出來施捨周濟大眾的財富反而更加廣泛博大！我依靠這三條謙退奉獻的原則來化解免除這三種必然的怨恨，您看可以嗎？狐丘丈人讚嘆道：講得太好了！這真是深諳保全大道的至理名言啊！","analysis":"【篇旨與孫叔敖三怨三對高處不勝寒政治防禦論】狐丘丈人揭示官場「爵高人妬、官大主惡、祿厚怨歸」之三大政治規律，孫叔敖以「志益下、心益小、施益博」三對破解，確立高階領導者謙遜自律的最高防身哲學。\\\\n【詞義訓詁】「三怨」：官場地位、權力、財富引發的嫉妒、猜忌與仇富必然規律；「志益下心益小施益博」：以謙卑化解嫉妒、以謹慎化解猜忌、以慈善化解仇富。\\\\n【領導力哲學】身居高位者必須具備高度的危機意識與分享精神，主動做權力與財富的減法，方能行穩致遠。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-18_s-1","liezi_ch-8_p-18_s-2","liezi_ch-8_p-18_s-3","liezi_ch-8_p-18_s-4","liezi_ch-8_p-18_s-5","liezi_ch-8_p-18_s-6","liezi_ch-8_p-18_s-7","liezi_ch-8_p-18_s-8","liezi_ch-8_p-18_s-9","liezi_ch-8_p-18_s-10"]},{"id":"liezi_ch-8_p-19","workId":"liezi","chapterId":"liezi_ch-8","index":19,"canonicalText":"孫叔敖疾將死，戒其子曰：「王亟封我矣，吾不受也。為我死，王則封汝。汝必無受利地！楚、越之閒，有寢丘者，此地不利而名甚惡。楚人鬼而越人禨，可長有者唯此也。」孫叔敖死，王果以美地封其子。子辭而不受，請寢丘。與之，至今不失。","readingAid":{"translation":"楚相孫叔敖身患重病臨終前夕，特地嚴肅告誡自己的兒子說：楚王屢次三番想將最肥美富饒的土地分封給我，我都堅決推辭不敢接受。等我死後，楚王必定會因為感念我的功勳而加倍分封你。你記住：千萬絕對不要接受任何肥沃富庶的有利土地（無受利地）！在楚國與越國交界荒涼的邊境地帶，有一塊名叫寢丘的荒涼土地，那裡土地極其貧瘠不利農耕，而且地名在世俗看來極其兇險不吉利。楚國人極度迷信鬼神，越國人極度忌諱凶兆占卜，全天下能夠世代長久守護保全的土地，唯獨只有這塊荒涼的寢丘啊！孫叔敖死後，楚王果然拿著最肥沃富庶的膏腴美地要重重分封他的兒子。孫叔敖的兒子堅決推辭不敢接受，唯獨主動懇請楚王將荒涼的寢丘賜給自己。楚王於是將寢丘封給了他，這塊封地孫家子孫世代承襲，歷經數百年風雲變幻直到今天也從未被任何權貴爭奪搶佔遺失！","analysis":"【篇旨與孫叔敖戒子受寢丘無用之用家族長青智慧】孫叔敖臨終告誡子嗣「無受利地、唯請寢丘」，利用土地貧瘠與名惡鬼禨（無用之用）避開歷代權貴爭奪，保全家族數百年基業不失。\\\\n【詞義訓詁】「寢丘」：楚越邊境貧瘠荒丘；「楚人鬼越人禨」：禨，音機，迷信吉凶禁忌；利用文化禁忌保護資產；「至今不失」：無用之用的最高歷史驗證。\\\\n【家族傳承智慧】最誘人的肥肉最易引發血腥爭奪，主動選擇低調、邊緣且具備防禦性的資產，是跨越週期保全家族的最優策略。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-19_s-1","liezi_ch-8_p-19_s-2","liezi_ch-8_p-19_s-3","liezi_ch-8_p-19_s-4","liezi_ch-8_p-19_s-5","liezi_ch-8_p-19_s-6","liezi_ch-8_p-19_s-7","liezi_ch-8_p-19_s-8"]},{"id":"liezi_ch-8_p-20","workId":"liezi","chapterId":"liezi_ch-8","index":20,"canonicalText":"牛缺者，上地之大儒也，下之邯鄲，遇盜於耦沙之中，盡取其衣裝車，牛步而去。視之，歡然無憂吝之色。盜追而問其故。曰：「君子不以所養害其所養。」盜曰：「嘻！賢矣夫！」既而相謂曰：「以彼之賢，往見趙君。便以我為，必困我。不如殺之。」乃相與追而殺之。燕人聞之，聚族相戒，曰：「遇盜莫如上地之牛缺也！」皆受教。俄而其弟適秦，至闕下，果遇盜。憶其兄之戒，因與盜力爭；既而不如，又追而以卑辭請物。盜怒曰：「吾活汝弘矣，而追吾不已，跡將箸焉。既為盜矣，仁將焉在？」遂殺之，又傍害其黨四五人焉。","readingAid":{"translation":"上地有一位聲名顯赫的大儒名叫牛缺，他啟程前往趙國都城邯鄲，在耦沙的荒漠之中遭遇了強盜劫匪。強盜搶光了他的全部衣服、行囊與馬車，牛缺只能步行安詳離去。強盜回頭遠遠觀察他，發現他滿臉歡喜坦蕩，臉上竟然毫無一絲憂愁吝嗇的痛惜之色。強盜追上去好奇詢問原因。牛缺坦然回答說：有德君子絕不會拿用來養育生命的物質身外之物（所養），去反過來傷害損害自己寶貴的生命本身（其所養）啊！強盜驚呼讚嘆道：哎呀！這真是一位天下大賢人啊！然而強盜轉身離開後，強盜同夥之間互相商議說：憑藉他這般卓越的大賢名望，到了邯鄲去面見趙國國君，一旦向國君提及我們的強盜罪行，趙王必定會派大軍將我們圍剿困死。與其等死，不如現在就追上去把他殺了滅口！於是強盜追上去將牛缺殘忍殺害了！燕國人聽聞這場悲劇後，召集全家族共同引以為戒告誡說：出門遭遇強盜，千萬不要學上地牛缺那樣裝出一副超凡脫俗的賢人模樣啊！全族人都接受了這個教訓。不久之後燕國有一個人的弟弟前往秦國，走到函谷關城闕之下，果然也遭遇了強盜打劫。他時刻牢記著哥哥當年的告誡（不可學牛缺超脫），於是在現場同強盜拼死激烈爭奪搏鬥；隨後打不過強盜被搶走財物後，他又緊追不捨在後面用卑微言辭苦苦哀求強盜歸還財物。強盜勃然大怒道：老子留你一條活命已經是天大的寬宏大量了，你竟然還在後面沒完沒了追蹤跟隨我們，我們的行蹤痕跡馬上就要被你暴露了！我們既然已經做了強盜，哪裡還會對你講什麼仁義道德！於是強盜當場手起刀落將他殘忍殺害，並順手將同行的四五個同伴也全部殘忍滅口殺害了！","analysis":"【篇旨與牛缺遇盜超脫與爭奪兩皆致死極端教條批判】極具黑色幽默與悲劇色彩之雙重公案——牛缺超然物外反因「賢名威脅」遭強盜滅口，其弟吸取教訓拼死爭奪糾纏反因「暴露行蹤」遭滅口，深刻揭示教條主義應對危機必致毀滅。\\\\n【詞義訓詁】「不以所養害其所養」：不因身外之物損害生命；「便以我為必困我」：過度卓越引發惡人猜忌防禦；「跡將箸焉」：箸通著，行蹤暴露。\\\\n【危機應變哲學】面對亡命之徒，無論是過度裝高尚炫耀賢名，還是過度糾纏激怒對方，皆屬致命取死之道；唯有審時度勢、因地制宜方能保全性命。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-20_s-1","liezi_ch-8_p-20_s-2","liezi_ch-8_p-20_s-3","liezi_ch-8_p-20_s-4","liezi_ch-8_p-20_s-5","liezi_ch-8_p-20_s-6","liezi_ch-8_p-20_s-7","liezi_ch-8_p-20_s-8","liezi_ch-8_p-20_s-9","liezi_ch-8_p-20_s-10","liezi_ch-8_p-20_s-11","liezi_ch-8_p-20_s-12","liezi_ch-8_p-20_s-13","liezi_ch-8_p-20_s-14","liezi_ch-8_p-20_s-15","liezi_ch-8_p-20_s-16","liezi_ch-8_p-20_s-17","liezi_ch-8_p-20_s-18"]},{"id":"liezi_ch-8_p-21","workId":"liezi","chapterId":"liezi_ch-8","index":21,"canonicalText":"虞氏者，梁之富人也，家充殷盛，錢帛無量，財貨無訾。登高樓，臨大路，設樂陳酒，擊博樓上，俠客相隨而行，樓上博者射，明瓊張中，反兩㯓魚而笑。飛鳶適墜其腐鼠而中之。俠客相與言曰：「虞氏富樂之日久矣，而常有輕易人之志。吾不侵犯之，而乃辱我以腐鼠。此而不報，無以立慬於天下。請與若等戮力一志，率徒屬，必滅其家為等倫。」皆許諾。至期日之夜，聚眾積兵，以攻虞氏，大滅其家。","readingAid":{"translation":"虞氏是魏國大樑城中的鉅富豪門，家境殷實富甲一方，金錢布帛無可計量，各類奇珍財富無可估價。虞氏家族在大道旁修築了巍峨的高樓，面臨繁華大路，在樓上擺設盛大歌舞美酒宴席，賓客們在樓上熱烈投壺擲骰賭博作樂。這時有一幫江湖俠客正成羣結隊從樓下大路上昂首走過；樓上賭博投骰的人正在興高采烈擲骰射中，骰子翻出絕妙好彩（明瓊張中），賭客們拍手歡呼開懷大笑。恰在這時，天空中一隻飛翔的老鷹（飛鳶）嘴裡叼著的一隻腐爛死老鼠偶然失爪掉了下來，正好不偏不倚砸中了樓下為首的那名俠客！俠客們頓時勃然大怒互相商議說：虞氏家族富貴享樂的日子太久了，平時就慣常懷有傲慢輕視天下人的狂妄之心！我們從未主動侵犯過他，他如今竟然故意用死老鼠從樓上砸下來公然侮辱我們！這等奇恥大辱如果不血債血償報復，我們今後還如何在全天下江湖上樹立勇武名節（立慬於天下）！請允許我同各位同心協力團結一致，率領全體門徒部屬，必定在今夜將虞氏家族徹底滅門滿門抄斬！眾俠客紛紛歃血許諾。到了約定日期的當天深夜，俠客們糾集了大批黑幫暴徒囤積精銳兵刃，趁夜突襲圍攻虞氏莊園，將虞氏滿門家族徹底殺光滅門！","analysis":"【篇旨與虞氏腐鼠滅門無妄之災與傲慢代價】先秦最驚心動魄的「無妄之災與社會仇恨」寓言——豪門虞氏臨街炫富聚賭，天降飛鳶腐鼠砸中路過俠客，引發俠客將偶然意外歸咎為「富豪蓄意辱我」而慘遭滅門。\\\\n【詞義訓詁】「財貨無訾」：訾，音紫，計量；財富無法估量；「明瓊張中」：瓊，骰子；擲骰中彩；「立慬於天下」：慬，音僅，勇武威名；「大滅其家」：滿門被屠滅。\\\\n【社會心理學啟示】炫富露富、臨街囂張往往會積聚深厚的社會階級怨恨；一旦遭遇偶發意外，積怨瞬間被引爆為毀滅性的滅頂之災。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-21_s-1","liezi_ch-8_p-21_s-2","liezi_ch-8_p-21_s-3","liezi_ch-8_p-21_s-4","liezi_ch-8_p-21_s-5","liezi_ch-8_p-21_s-6","liezi_ch-8_p-21_s-7","liezi_ch-8_p-21_s-8","liezi_ch-8_p-21_s-9"]},{"id":"liezi_ch-8_p-22","workId":"liezi","chapterId":"liezi_ch-8","index":22,"canonicalText":"東方有人焉，曰爰旌目，將有適也，而餓於道。狐父之盜曰丘，見而下壺餐以餔之。爰旌目三餔而後能視，曰：「子何為者也？」曰：「我狐父之人丘也。」爰旌目曰：「譆！汝非盜邪？胡為而餐我？吾義不食子之食也。」兩手據地而歐之，不出，喀喀然遂伏而死。狐父之人則盜矣，而食非盜也。以人之盜，因謂食為盜而不敢食，是失名實者也。","readingAid":{"translation":"東方有一個士人名叫爰旌目，準備出門遠行前往某地，在半路上糧食斷絕飢腸轆轆倒在路邊等死。狐父地方的一位名叫丘的強盜盜匪路過此地，看見他快要餓死了，心生憐憫急忙解下自己隨身攜帶的竹壺乾糧水飯（壺餐）餵給他喫。爰旌目狼吞虎嚥吃了三口之後，體力恢復終於能夠睜開眼睛看清人了，他問道：您究竟是什麼人呀？強盜回答說：我是狐父那個地方的人，名字叫丘。爰旌目大驚失色驚呼道：哎呀！你難道不就是那個臭名昭著的大強盜嗎？你為什麼要拿食物給我喫？我秉持大義絕對不能喫你這個強盜施捨的骯髒食物！說罷，他雙手趴在地上用手指死命扣喉嚨催吐（歐之），食物早已消化卡在喉嚨裡嘔吐不出來，他劇烈咳嗽乾嘔（喀喀然），最終活活趴在地上吐血而死！狐父的那個人本身雖然確實是個強盜，但那壺乾糧食物本身卻並不是強盜啊！因為人是強盜，就荒謬地把客觀食物也認定為強盜而堅決不肯食用，這正是完全喪失了概念名稱（名）與客觀實質（實）之辨的極端教條愚蠢之輩啊！","analysis":"【篇旨與爰旌目不食盜食名實混淆教條道德悲劇】名辯學與倫理學批判名篇——爰旌目快餓死時食盜糧得活，知其為盜後「據地嘔之喀喀伏死」，作者痛批其「人雖盜而食非盜，以人為盜謂食為盜」，揭露道德教條主義混淆名實草菅人命。\\\\n【詞義訓詁】「餔」：餔，音布，餵食、進食；「歐之」：歐通嘔，催吐嘔吐；「失名實」：概念指涉混亂，將主體道德屬性荒謬泛化至客觀無辜客體。\\\\n【教條主義批判】批判不顧客觀事實與生存底線的極端道德潔癖，確立名實分離的客觀理性原則。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-22_s-1","liezi_ch-8_p-22_s-2","liezi_ch-8_p-22_s-3","liezi_ch-8_p-22_s-4","liezi_ch-8_p-22_s-5","liezi_ch-8_p-22_s-6","liezi_ch-8_p-22_s-7","liezi_ch-8_p-22_s-8","liezi_ch-8_p-22_s-9","liezi_ch-8_p-22_s-10","liezi_ch-8_p-22_s-11"]},{"id":"liezi_ch-8_p-23","workId":"liezi","chapterId":"liezi_ch-8","index":23,"canonicalText":"柱厲叔事莒敖公，自為不知己，去，居海上。夏日則食菱芰，冬日則食橡栗。莒敖公有難，柱厲叔辭其友而往死之。其友曰：「子自以為不知己，故去；今往死之，是知與不知無辨也。」柱厲叔曰：「不然。自以為不知，故去；今死，是果不知我也。吾將死之，以醜後世之人主不知其臣者也。」凡知則死之，不知則弗死，此直道而行者也。柱厲叔可謂懟以忘其身者也。","readingAid":{"translation":"柱厲叔侍奉莒國國君莒敖公，自認為莒敖公根本不懂得賞識理解自己的才華（不知己），於是毅然辭職離開宮廷，隱居在荒涼的大海之濱。夏天就採摘水中的菱角芰草為食，冬天就撿拾山中的橡子板栗充飢。後來莒敖公遭遇了政治政變國難被弒殺，柱厲叔聽聞後告別好友，準備親自前往莒國為莒敖公殉節赴死。他的好友震驚地勸阻他說：您當年自己認為國君不賞識了解您，所以才憤而辭職離去；如今國君有難您卻偏偏要跑去為他送死，這豈不是把賞識你與不賞識你的根本界限搞得毫無分別了嗎？柱厲叔回答說：完全不是這樣的！我當年自認為他不賞識我，所以憤而辭職離去；如今他遭遇大難我前往赴死，這恰恰徹底坐實了他當年確實根本不了解我的高尚節操！我今天偏偏要用我的慷慨赴死，來讓後世所有不識英才、怠慢忠良的昏庸君主感到無地自容與羞恥（以醜後世之人主）！按常理而言：君主真正賞識知己才為他赴死，君主不賞識自己就絕不為他白白送死，這才是遵循正常正道的處事法則；而柱厲叔這種行為，可以說是純粹被內心的憤懣怨恨所沖昏頭腦而白白葬送自己寶貴生命的極端偏執之人啊！","analysis":"【篇旨與柱厲叔為不知己者死負氣殉節心理剖析】深刻剖析戰國死士畸形心理——柱厲叔因國君不知己而離去，又為「以醜後世不知臣之主」而赴死殉難，作者精闢評判為「懟以忘其身（因負氣怨恨而白白葬送生命）」之偏執。\\\\n【詞義訓詁】「菱芰」：芰，音記，菱角；「以醜後世之人主」：醜，使動用法，使後世昏君感到羞愧醜陋；「懟以忘身」：懟，音對，怨恨憤懣；被負面情緒綁架做無謂犧牲。\\\\n【心理學批判】揭露以自我毀滅為代價去報復或教育他人的荒謬性，批判病態的道德表演與負氣殉葬。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-23_s-1","liezi_ch-8_p-23_s-2","liezi_ch-8_p-23_s-3","liezi_ch-8_p-23_s-4","liezi_ch-8_p-23_s-5","liezi_ch-8_p-23_s-6","liezi_ch-8_p-23_s-7","liezi_ch-8_p-23_s-8","liezi_ch-8_p-23_s-9","liezi_ch-8_p-23_s-10","liezi_ch-8_p-23_s-11"]},{"id":"liezi_ch-8_p-24","workId":"liezi","chapterId":"liezi_ch-8","index":24,"canonicalText":"白公勝慮亂，罷朝而立，倒杖策，錣上貫頤，血流至地而弗知也。鄭人聞之曰：「頤之忘，將何不忘哉？」意之所屬箸，其行足躓株埳，頭抵植木，而不自知也。故心有所專，則身有所忘；意有所蔽，則理有所遺。","readingAid":{"translation":"楚國大夫白公勝在暗中策劃發動武裝叛亂奪權（慮亂），退朝之後獨自肅立在朝堂門外陷入極度苦思冥想，他不自覺地把手中的馬鞭柺杖倒拿著（倒杖策），馬鞭末端鋒利的鐵針倒刺直接深深扎穿貫穿了他的下巴下顎（錣上貫頤），鮮血順著下巴滴淌流淌到了地上染紅了地面，而他自己竟然完全渾然不覺！鄭國人聽聞這件事後感慨說：連自己下巴肉體被利刃刺穿的劇痛都能徹底忘記，世上還有什麼是他不能忘卻的呢？當一個人的全副心智意念極度專注執迷於某一個特定目標之際（意之所屬箸），他走起路來雙腳被樹樁泥坑絆倒（足躓株埳），腦袋直接迎面撞擊在直立的樹木柱子上，自己都完全察覺不到！所以當內心被某種極端執念所專注綁架時，肉體身體就會被徹底遺忘麻木；當意念被某種偏執陰謀所嚴重遮蔽障礙之際，客觀大道的真理規律就會被徹底丟失遺漏啊！","analysis":"【篇旨與白公勝錣貫頤慮亂極端執迷痛覺麻木心理學】先秦極度震撼的心理學案例——白公勝密謀政變高度專注致馬鞭鐵刺穿透下巴血流滿地而渾然不覺，揭示「意之所屬箸、心專身忘、意蔽理遺」的認知盲區與痛覺阻斷機制。\\\\n【詞義訓詁】「慮亂」：密謀發動武裝叛亂；「倒杖策」：策，馬鞭；倒持馬鞭；「錣上貫頤」：錣，音綴，馬鞭末端鐵針；頤，音移，下巴；鐵針穿透下巴；「意所屬箸」：箸通著，附著、聚焦。\\\\n【神經心理學】高度心理聚焦與焦慮能引發大腦內啡肽強烈分泌而阻斷痛覺感知，警示極端偏執必將導致認知盲區與毀滅性盲動。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-24_s-1","liezi_ch-8_p-24_s-2","liezi_ch-8_p-24_s-3","liezi_ch-8_p-24_s-4","liezi_ch-8_p-24_s-5"]},{"id":"liezi_ch-8_p-25","workId":"liezi","chapterId":"liezi_ch-8","index":25,"canonicalText":"昔齊人有欲金者，清旦衣冠而之市，適鬻金者之所，因攫其金而去。吏捕得之，問曰：「人皆在焉，子攫人之金何？」對曰：「取金之時，不見人，徒見金。」說符篇終。子列子曰：「天下之惑，皆由意蔽也。齊人之攫金，白公之貫頤，其蔽於物一也。能去其蔽，反於虛靜，則天下之符，莫不相合矣。」","readingAid":{"translation":"從前齊國有一個極度貪戀金銀財富的人（欲金者），大清早穿戴好衣帽走到繁華街市之上，徑直來到販賣黃金的金鋪攤位前，趁人不備一把搶奪抓起攤上的黃金拔腿就跑（攫金而去）！官府差役巡捕當場將他抓獲捕獲，審訊他問道：滿大街全是來來往往的巡警差役與市民百姓，你怎麼敢在光天化日之下公然搶奪別人的黃金呢？那人坦然回答說：我剛才動手拿黃金的時候，我眼睛裡根本看不見有任何人的存在，我的眼裡唯獨只看見金光閃閃的黃金罷了！〈說符〉全篇總結。列子感嘆說：全天下世人之所以會陷入無盡的困惑與犯罪悲劇，全都是因為心靈被外在物慾所嚴重遮蔽蒙蔽（意蔽）的緣故啊！齊國人光天化日搶奪黃金，白公勝策劃政變鐵刺穿透下巴，他們在心智被身外之物所障蔽這一點上是完全同一回事情啊！如果能夠自覺徹底掃除這一切物慾偏見的障蔽，重新回歸內心的虛極清靜，那麼全天下世間萬事萬物的因果符節徵兆，就沒有哪一個不能精準相合相應了啊！","analysis":"【篇旨與齊人攫金徒見金說符全篇大結尾去蔽反虛靜】先秦心理學與犯罪學千古絕唱——「齊人攫金不見人徒見金」生動揭示物慾狂熱導致的「管窺效應（Tunnel Vision）」，列子以「去蔽反於虛靜、天下之符莫不相合」總結全書，確立心靈澄明方能洞悉因果規律的至高境界。\\\\n【詞義訓詁】「鬻金者」：鬻，音育，賣金商鋪；「攫金」：攫，音決，抓取搶奪；「徒見金」：視野被貪婪完全佔據；「去蔽反於虛靜」：掃除名利執念、恢復心齋澄明。\\\\n【全書終極哲學收官】《列子》八卷（天瑞、黃帝、周穆王、仲尼、湯問、力命、楊朱、說符）至此圓滿收官，系統建構了涵蓋宇宙生成、心流技藝、夢境心理、名辯邏輯、科幻神話、力命平衡、個體尊嚴與因果符驗的宏偉道家思想體系。","historicalContext":"","keywords":[]},"sourceRefs":[{"label":"《列子》—中國哲學書電子化計劃","edition":"楊伯峻《列子集釋》本","location":"https://ctext.org/liezi/zh","accessedAt":"2026-08-31"},{"label":"《列子》—維基文庫","edition":"張湛《列子注》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/列子","accessedAt":"2026-08-31"}],"sentenceIds":["liezi_ch-8_p-25_s-1","liezi_ch-8_p-25_s-2","liezi_ch-8_p-25_s-3","liezi_ch-8_p-25_s-4","liezi_ch-8_p-25_s-5","liezi_ch-8_p-25_s-6","liezi_ch-8_p-25_s-7","liezi_ch-8_p-25_s-8"]}],"sentences":[{"id":"liezi_ch-8_p-1_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":1,"canonicalText":"子列子學於壺丘子林。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":2,"canonicalText":"壺丘子林曰：「子知持後，則可言持身矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":3,"canonicalText":"」列子曰：「願聞持後。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":4,"canonicalText":"」曰：「顧若影，則知之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":5,"canonicalText":"」列子顧而觀影：形枉則影曲，形直則影正。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":6,"canonicalText":"然則枉直者，定在於形，不在於影。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":7,"canonicalText":"形動作於先，影隨應於後。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-1_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-1","order":8,"canonicalText":"持後之道，因形以應變也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":1,"canonicalText":"關尹謂子列子曰：「言美者應美，言惡者應惡；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":2,"canonicalText":"身大者影大，身小者影小。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":3,"canonicalText":"名自命也，事自應也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":4,"canonicalText":"故善言者，美應自至；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":5,"canonicalText":"善行者，福祿自來。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":6,"canonicalText":"慎其所發，則知其所歸矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-2_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-2","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-3_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-3","order":1,"canonicalText":"子列子曰：「天下之物，莫不由符而驗。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-3_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-3","order":2,"canonicalText":"發於此而應於彼，動於微而顯於著。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-3_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-3","order":3,"canonicalText":"善為符者，見其萌而知其終，睹其始而識其成。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-3_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-3","order":4,"canonicalText":"此說符之大要也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-3_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-3","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":1,"canonicalText":"晉文公出亡，過曹，曹共公不禮焉，欲觀其駢脅，駢脅而浴。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":2,"canonicalText":"僖負羈之妻曰：「吾觀晉公子，從者三人，皆霸王之佐也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":3,"canonicalText":"公子若反國，必霸諸侯，而誅無禮。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":4,"canonicalText":"曹其首也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":5,"canonicalText":"子何不先自結焉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":6,"canonicalText":"」僖負羈乃饋盤飧，寘璧焉。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":7,"canonicalText":"文公受飧而反璧。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":8,"canonicalText":"及文公即位，興兵伐曹，入其國，令三軍毋入僖負羈之宮。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-4_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-4","order":9,"canonicalText":"故知先機者存，慢禮者亡。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":1,"canonicalText":"楚莊王伐陳，勝之，欲以為縣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":2,"canonicalText":"申叔時使於齊反，謁王。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":3,"canonicalText":"王曰：「陳可為縣乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":4,"canonicalText":"」對曰：「不可。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":5,"canonicalText":"昔者有牽牛以蹊人之田而奪之牛者，牽牛蹊田，信有罪矣；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":6,"canonicalText":"而奪之牛，罰亦重矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":7,"canonicalText":"今陳侯有罪，君伐而縣之，何以示天下之公乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":8,"canonicalText":"」莊王乃封陳而還。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-5_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-5","order":9,"canonicalText":"天下皆服其義。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":1,"canonicalText":"子列子居鄭圃，食不足，面有飢色。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":2,"canonicalText":"客有言之鄭子產曰：「列禦寇，蓋有道之士也，居君之國而窮，君無乃為不好士乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":3,"canonicalText":"」子產乃使官往遺之粟。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":4,"canonicalText":"子列子出見使者，再拜而辭。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":5,"canonicalText":"使者去，妻望之而拊心曰：「妾聞為悌子者，妻子蒙福。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":6,"canonicalText":"今先生面有飢色，客遺之粟，先生不受，命也夫！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":7,"canonicalText":"」子列子笑曰：「子產非自知我也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":8,"canonicalText":"以人之言而遺我粟，至其罪我也，亦必以人之言。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":9,"canonicalText":"吾是以不受也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-6_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-6","order":10,"canonicalText":"」其後，民果作難，子產治之，受其賜者皆獲罪，唯列子免焉。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-7_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-7","order":1,"canonicalText":"楊朱曰：「利出者實及，怨往者害來。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-7_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-7","order":2,"canonicalText":"發於此而應於外者唯情，是故賢者慎所出。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-7_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-7","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":1,"canonicalText":"楊子之鄰人亡羊，既率其黨，又請楊子之豎追之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":2,"canonicalText":"楊子曰：「嘻！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":3,"canonicalText":"亡一羊何追者之眾？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":4,"canonicalText":"」鄰人曰：「多岐路。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":5,"canonicalText":"」既反，問：「獲羊乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":6,"canonicalText":"」曰：「亡之矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":7,"canonicalText":"」曰：「奚亡之？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":8,"canonicalText":"」曰：「岐路之中又有岐焉，吾不知所之，所以反也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":9,"canonicalText":"」楊子戚然變容，不言者移時，不笑者竟日。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":10,"canonicalText":"門人怪之，請曰：「羊，賤畜，又非夫子之有，而損言笑者何哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-11","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":11,"canonicalText":"」楊子不答，門人不獲所命。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-12","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":12,"canonicalText":"弟子孟孫陽出，以告心都子。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-13","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":13,"canonicalText":"心都子他日與孟孫陽偕入，而問曰：「昔有昆弟三人，遊齊、魯之間，同師而學，進仁義之道而歸。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-14","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":14,"canonicalText":"其父曰：『仁義之道若何？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-15","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":15,"canonicalText":"』伯曰：『仁義使我愛身而後名。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-16","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":16,"canonicalText":"』仲曰：『仁義使我殺身以成名。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-17","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":17,"canonicalText":"』叔曰：『仁義使我身名並全。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-18","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":18,"canonicalText":"』彼三術相反，而同出於儒。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-19","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":19,"canonicalText":"孰是孰非邪？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-20","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":20,"canonicalText":"」楊子曰：「人有濱河而居者，習於水，勇於泅，操舟鬻渡，利供百口，裹糧就學者成徒，而溺死者幾半。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-21","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":21,"canonicalText":"本學泅不學溺，而利害如此。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-22","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":22,"canonicalText":"若以為孰是孰非？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-23","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":23,"canonicalText":"」心都子嘿然而出。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-24","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":24,"canonicalText":"孟孫陽讓之曰：「何吾子問之迂，夫子答之僻？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-25","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":25,"canonicalText":"吾惑愈甚。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-26","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":26,"canonicalText":"」心都子曰：「大道以多岐亡羊，學者以多方喪生。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-27","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":27,"canonicalText":"學非本不同，非本不一，而末異若是。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-28","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":28,"canonicalText":"唯歸同反一，為亡得喪。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-29","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":29,"canonicalText":"子長先生之門，習先生之道，而不達先生之況也，哀哉！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-8_s-30","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-8","order":30,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":1,"canonicalText":"楊朱之弟曰布，衣素衣而出。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":2,"canonicalText":"天雨，解素衣，衣緇衣而反。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":3,"canonicalText":"其狗不知，迎而吠之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":4,"canonicalText":"楊布怒，將撲之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":5,"canonicalText":"楊朱曰：「子無撲矣，子亦猶是也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":6,"canonicalText":"嚮者使汝狗白而往，黑而來，豈能無怪哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-9_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-9","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-10_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-10","order":1,"canonicalText":"楊朱曰：「行善不以為名而名從之；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-10_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-10","order":2,"canonicalText":"名不與利期而利歸之；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-10_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-10","order":3,"canonicalText":"利不與爭期而爭及之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-10_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-10","order":4,"canonicalText":"故君子必慎為善。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-10_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-10","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":1,"canonicalText":"昔人言有知不死之道者，燕君使人受之，不捷，而言者死。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":2,"canonicalText":"燕君甚怒其使者，將加誅焉。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":3,"canonicalText":"倖臣諫曰：「人所憂者莫急乎死，己所重者莫過乎生。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":4,"canonicalText":"彼自喪其生，安能令君不死也？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":5,"canonicalText":"」乃不誅。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":6,"canonicalText":"有齊子亦欲學其道，聞言者之死，乃撫膺而恨。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":7,"canonicalText":"富子聞而笑之曰：「夫所欲學不死，其人已死，而猶恨之，是不知所以為學。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":8,"canonicalText":"」鬍子曰：「富子之言非也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":9,"canonicalText":"凡人有術不能行者有矣，能行而無其術者亦有矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":10,"canonicalText":"衛人有善數者，臨死，以決喻其子。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-11","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":11,"canonicalText":"志其言而不能行也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-12","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":12,"canonicalText":"他人問之，以其父所言告之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-13","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":13,"canonicalText":"問者用其言而行其術，與其父無差焉。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-14","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":14,"canonicalText":"若然，死者奚為不能言生術哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-11_s-15","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-11","order":15,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":1,"canonicalText":"邯鄲之民，以正月之旦獻鳩於簡子，簡子大悅，厚賞之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":2,"canonicalText":"客問其故。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":3,"canonicalText":"簡子曰：「正旦放生，示有恩也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":4,"canonicalText":"」客曰：「民知君之慾放之，故競而捕之，死者眾矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":5,"canonicalText":"君如欲生之，不若禁民勿捕。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":6,"canonicalText":"捕而放之，恩過不相補矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":7,"canonicalText":"」簡子曰：「然。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-12_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-12","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":1,"canonicalText":"齊田氏祖於庭，食客千人。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":2,"canonicalText":"中坐有獻魚鴈者。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":3,"canonicalText":"田氏視之，乃歎曰：「天之於民厚矣！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":4,"canonicalText":"殖五穀，生魚鳥，以為之用。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":5,"canonicalText":"」眾客和之如響。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":6,"canonicalText":"鮑氏之子年十二，預於次，進曰：「不如君言。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":7,"canonicalText":"天地萬物，與我並生類也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":8,"canonicalText":"類無貴賤，徒以小大智力而相制，迭相食；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":9,"canonicalText":"非相為而生之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":10,"canonicalText":"人取可食者而食之，豈天本為人生之？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-11","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":11,"canonicalText":"且蚊蚋噆膚，虎狼食肉，非天本為蚊蚋生人、虎狼生肉者哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-13_s-12","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-13","order":12,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":1,"canonicalText":"齊有貧者，常乞於城市。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":2,"canonicalText":"城市患其亟也，眾莫之與。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":3,"canonicalText":"遂適田氏之廄，從馬醫作役，而假食郭中。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":4,"canonicalText":"人戲之曰：「從馬醫而食，不以辱乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":5,"canonicalText":"」乞兒曰：「天下之辱莫過於乞。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":6,"canonicalText":"乞猶不辱，豈辱馬醫哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-14_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-14","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-15_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-15","order":1,"canonicalText":"宋人有遊於道，得人遺契者，歸而藏之，密數其齒。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-15_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-15","order":2,"canonicalText":"告鄰人曰：「吾富可待矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-15_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-15","order":3,"canonicalText":"」鄰人曰：「契者，彼之券也，非汝之積也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-15_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-15","order":4,"canonicalText":"無實而求得，惑之甚矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-15_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-15","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-16_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-16","order":1,"canonicalText":"人有枯梧樹者，其鄰父言枯梧之樹不祥。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-16_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-16","order":2,"canonicalText":"其人遽而伐之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-16_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-16","order":3,"canonicalText":"鄰人父因請以為薪。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-16_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-16","order":4,"canonicalText":"其人乃不悅曰：「鄰人之父徒欲為薪，而教吾伐之也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-16_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-16","order":5,"canonicalText":"與我鄰若此，其險豈可哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-16_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-16","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-17_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-17","order":1,"canonicalText":"人有亡鈇者，意其鄰之子。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-17_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-17","order":2,"canonicalText":"視其行步，竊鈇也；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-17_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-17","order":3,"canonicalText":"顏色，竊鈇也；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-17_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-17","order":4,"canonicalText":"言語，竊鈇也；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-17_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-17","order":5,"canonicalText":"作動態度，無為而不竊鈇也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-17_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-17","order":6,"canonicalText":"俄而抇其谷而得其鈇，他日復見其鄰人之子，動作態度，無似竊鈇者。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":1,"canonicalText":"狐丘丈人謂孫叔敖曰：「人有三怨，子知之乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":2,"canonicalText":"」孫叔敖曰：「何謂也？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":3,"canonicalText":"」對曰：「爵高者人妬之，官大者主惡之，祿厚者怨歸之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":4,"canonicalText":"」孫叔敖曰：「吾爵益高，吾志益下；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":5,"canonicalText":"吾官益大，吾心益小；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":6,"canonicalText":"吾祿益厚，吾施益博。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":7,"canonicalText":"以是免於三怨，可乎？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":8,"canonicalText":"」狐丘丈人曰：「善哉！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":9,"canonicalText":"言乎。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-18_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-18","order":10,"canonicalText":"」","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":1,"canonicalText":"孫叔敖疾將死，戒其子曰：「王亟封我矣，吾不受也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":2,"canonicalText":"為我死，王則封汝。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":3,"canonicalText":"汝必無受利地！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":4,"canonicalText":"楚、越之閒，有寢丘者，此地不利而名甚惡。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":5,"canonicalText":"楚人鬼而越人禨，可長有者唯此也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":6,"canonicalText":"」孫叔敖死，王果以美地封其子。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":7,"canonicalText":"子辭而不受，請寢丘。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-19_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-19","order":8,"canonicalText":"與之，至今不失。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":1,"canonicalText":"牛缺者，上地之大儒也，下之邯鄲，遇盜於耦沙之中，盡取其衣裝車，牛步而去。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":2,"canonicalText":"視之，歡然無憂吝之色。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":3,"canonicalText":"盜追而問其故。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":4,"canonicalText":"曰：「君子不以所養害其所養。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":5,"canonicalText":"」盜曰：「嘻！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":6,"canonicalText":"賢矣夫！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":7,"canonicalText":"」既而相謂曰：「以彼之賢，往見趙君。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":8,"canonicalText":"便以我為，必困我。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":9,"canonicalText":"不如殺之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":10,"canonicalText":"」乃相與追而殺之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-11","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":11,"canonicalText":"燕人聞之，聚族相戒，曰：「遇盜莫如上地之牛缺也！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-12","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":12,"canonicalText":"」皆受教。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-13","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":13,"canonicalText":"俄而其弟適秦，至闕下，果遇盜。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-14","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":14,"canonicalText":"憶其兄之戒，因與盜力爭；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-15","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":15,"canonicalText":"既而不如，又追而以卑辭請物。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-16","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":16,"canonicalText":"盜怒曰：「吾活汝弘矣，而追吾不已，跡將箸焉。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-17","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":17,"canonicalText":"既為盜矣，仁將焉在？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-20_s-18","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-20","order":18,"canonicalText":"」遂殺之，又傍害其黨四五人焉。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":1,"canonicalText":"虞氏者，梁之富人也，家充殷盛，錢帛無量，財貨無訾。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":2,"canonicalText":"登高樓，臨大路，設樂陳酒，擊博樓上，俠客相隨而行，樓上博者射，明瓊張中，反兩㯓魚而笑。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":3,"canonicalText":"飛鳶適墜其腐鼠而中之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":4,"canonicalText":"俠客相與言曰：「虞氏富樂之日久矣，而常有輕易人之志。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":5,"canonicalText":"吾不侵犯之，而乃辱我以腐鼠。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":6,"canonicalText":"此而不報，無以立慬於天下。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":7,"canonicalText":"請與若等戮力一志，率徒屬，必滅其家為等倫。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":8,"canonicalText":"」皆許諾。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-21_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-21","order":9,"canonicalText":"至期日之夜，聚眾積兵，以攻虞氏，大滅其家。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":1,"canonicalText":"東方有人焉，曰爰旌目，將有適也，而餓於道。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":2,"canonicalText":"狐父之盜曰丘，見而下壺餐以餔之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":3,"canonicalText":"爰旌目三餔而後能視，曰：「子何為者也？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":4,"canonicalText":"」曰：「我狐父之人丘也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":5,"canonicalText":"」爰旌目曰：「譆！","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":6,"canonicalText":"汝非盜邪？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":7,"canonicalText":"胡為而餐我？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":8,"canonicalText":"吾義不食子之食也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":9,"canonicalText":"」兩手據地而歐之，不出，喀喀然遂伏而死。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":10,"canonicalText":"狐父之人則盜矣，而食非盜也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-22_s-11","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-22","order":11,"canonicalText":"以人之盜，因謂食為盜而不敢食，是失名實者也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":1,"canonicalText":"柱厲叔事莒敖公，自為不知己，去，居海上。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":2,"canonicalText":"夏日則食菱芰，冬日則食橡栗。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":3,"canonicalText":"莒敖公有難，柱厲叔辭其友而往死之。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":4,"canonicalText":"其友曰：「子自以為不知己，故去；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":5,"canonicalText":"今往死之，是知與不知無辨也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":6,"canonicalText":"」柱厲叔曰：「不然。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":7,"canonicalText":"自以為不知，故去；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":8,"canonicalText":"今死，是果不知我也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-9","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":9,"canonicalText":"吾將死之，以醜後世之人主不知其臣者也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-10","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":10,"canonicalText":"」凡知則死之，不知則弗死，此直道而行者也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-23_s-11","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-23","order":11,"canonicalText":"柱厲叔可謂懟以忘其身者也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-24_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-24","order":1,"canonicalText":"白公勝慮亂，罷朝而立，倒杖策，錣上貫頤，血流至地而弗知也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-24_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-24","order":2,"canonicalText":"鄭人聞之曰：「頤之忘，將何不忘哉？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-24_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-24","order":3,"canonicalText":"」意之所屬箸，其行足躓株埳，頭抵植木，而不自知也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-24_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-24","order":4,"canonicalText":"故心有所專，則身有所忘；","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-24_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-24","order":5,"canonicalText":"意有所蔽，則理有所遺。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-1","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":1,"canonicalText":"昔齊人有欲金者，清旦衣冠而之市，適鬻金者之所，因攫其金而去。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-2","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":2,"canonicalText":"吏捕得之，問曰：「人皆在焉，子攫人之金何？","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-3","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":3,"canonicalText":"」對曰：「取金之時，不見人，徒見金。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-4","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":4,"canonicalText":"」說符篇終。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-5","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":5,"canonicalText":"子列子曰：「天下之惑，皆由意蔽也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-6","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":6,"canonicalText":"齊人之攫金，白公之貫頤，其蔽於物一也。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-7","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":7,"canonicalText":"能去其蔽，反於虛靜，則天下之符，莫不相合矣。","chunks":[],"tags":[]},{"id":"liezi_ch-8_p-25_s-8","workId":"liezi","chapterId":"liezi_ch-8","passageId":"liezi_ch-8_p-25","order":8,"canonicalText":"」","chunks":[],"tags":[]}]}');export{i as default};
